#!/data/data/com.termux/files/usr/bin/bash
set -e

echo "𓆙 GOJO WHATSAPP REPORTER — INSTALLATION"
echo

if [ -z "$PREFIX" ]; then
    echo "❌ Ouvre ce script dans Termux."
    exit 1
fi

echo "📦 Installation de Python..."
pkg update -y
pkg install -y python

echo "📚 Installation des dépendances..."
python -m pip install --break-system-packages python-dotenv

echo "📄 Installation du programme..."
echo "" | base64 -d > "$HOME/gojo.whatsapp.reporter.public.py"
chmod 700 "$HOME/gojo.whatsapp.reporter.public.py"

echo "🔎 Vérification..."
python -m py_compile "$HOME/gojo.whatsapp.reporter.public.py"

echo
echo "✅ Installation terminée."
echo "🚀 Lancement..."
echo

python "$HOME/gojo.whatsapp.reporter.public.py"
